package io
import("bytes";"context";"errors";"log/slog";"os";"path/filepath";"strings";"testing";"github.com/tetsup/flexraid/storage")
func testFileKey(id storage.StripeID)storage.FileKey{return storage.FileKey{ObjectID:storage.ObjectID{0x12,0x34,0x56,0x78,0x9a,0xbc,0x4d,0xef,0x8a,0xbc,0x12,0x34,0x56,0x78,0x90,0xab},StripeVersion:1,LayoutID:storage.LayoutID{Type:'X',DriveCount:5,Role:storage.ChunkRoleData,Index:1},StripeID:id}}
func newTestLayer(t testing.TB,root string)*IO{t.Helper();var b bytes.Buffer;return newTestLayerWithOutput(t,root,&b,slog.LevelDebug)}
func newTestLayerWithOutput(t testing.TB,root string,out *bytes.Buffer,level slog.Level)*IO{t.Helper();logger:=slog.New(slog.NewTextHandler(out,&slog.HandlerOptions{Level:level}));t.Cleanup(func(){if t.Failed()&&out.Len()>0{t.Logf("captured logs:\n%s",out.String())}});return New(NewRequest{Root:root,Logger:logger}).Layer}
func TestReadWriteDelete(t *testing.T){l:=newTestLayer(t,t.TempDir());ctx:=context.Background();k:=testFileKey(0);data:=[]byte("stripe data");w,e:=l.Write(WriteRequest{Context:ctx,Key:k,Data:data});if e!=nil{t.Fatal(e)};if w.BytesWritten!=len(data){t.Fatalf("wrote %d",w.BytesWritten)};if _,e=l.Write(WriteRequest{Context:ctx,Key:k,Data:[]byte("replacement")});!errors.Is(e,os.ErrExist){t.Fatalf("got %v",e)};r,e:=l.Read(ReadRequest{Context:ctx,Key:k});if e!=nil{t.Fatal(e)};if !bytes.Equal(r.Data,data){t.Fatalf("got %q",r.Data)};d,e:=l.Delete(DeleteRequest{Context:ctx,Key:k});if e!=nil||!d.Deleted{t.Fatalf("delete: %#v %v",d,e)};if _,e=l.Read(ReadRequest{Context:ctx,Key:k});!errors.Is(e,os.ErrNotExist){t.Fatalf("got %v",e)}}
func TestScanHeadersOnlyStripeZero(t *testing.T){l:=newTestLayer(t,t.TempDir());ctx:=context.Background();for _,k:=range []storage.FileKey{testFileKey(0),testFileKey(1)}{if _,e:=l.Write(WriteRequest{Context:ctx,Key:k,Data:[]byte("data")});e!=nil{t.Fatal(e)}};var found []ScanEntry;r,e:=l.ScanHeaders(ScanHeadersRequest{Context:ctx,Callback:func(v ScanEntry)error{found=append(found,v);return nil}});if e!=nil{t.Fatal(e)};if r.Entries!=1||len(found)!=1||found[0].Key.StripeID!=0{t.Fatalf("%#v %#v",r,found)}}
func TestListChunksIncludesEveryStripe(t *testing.T){l:=newTestLayer(t,t.TempDir());ctx:=context.Background();for _,id:=range []storage.StripeID{0,1,2}{if _,e:=l.Write(WriteRequest{Context:ctx,Key:testFileKey(id),Data:[]byte{byte(id)}});e!=nil{t.Fatal(e)}};var n int;r,e:=l.ListChunks(ListChunksRequest{Context:ctx,Callback:func(ScanEntry)error{n++;return nil}});if e!=nil{t.Fatal(e)};if r.Entries!=3||n!=3{t.Fatalf("entries=%d callbacks=%d",r.Entries,n)}}
func TestScanSkipsInvalidFilenameWithWarning(t *testing.T){root:=t.TempDir();var out bytes.Buffer;l:=newTestLayerWithOutput(t,root,&out,slog.LevelDebug);if _,e:=l.Write(WriteRequest{Context:context.Background(),Key:testFileKey(0),Data:[]byte("data")});e!=nil{t.Fatal(e)};if e:=os.WriteFile(filepath.Join(root,"invalid-file-name"),[]byte("x"),0644);e!=nil{t.Fatal(e)};r,e:=l.ScanHeaders(ScanHeadersRequest{Context:context.Background(),Callback:func(ScanEntry)error{return nil}});if e!=nil||r.Entries!=1{t.Fatalf("%#v %v",r,e)};if !strings.Contains(out.String(),"level=WARN"){t.Fatalf("logs %q",out.String())}}
func TestExpectedReadErrorIsDebugOnly(t *testing.T){var out bytes.Buffer;l:=newTestLayerWithOutput(t,t.TempDir(),&out,slog.LevelDebug);_,e:=l.Read(ReadRequest{Context:context.Background(),Key:testFileKey(0)});if !errors.Is(e,os.ErrNotExist){t.Fatalf("got %v",e)};if strings.Contains(out.String(),"level=WARN")||strings.Contains(out.String(),"level=ERROR"){t.Fatalf("logs %q",out.String())}}
func TestScanCallbackError(t *testing.T){l:=newTestLayer(t,t.TempDir());_,e:=l.Write(WriteRequest{Context:context.Background(),Key:testFileKey(0),Data:[]byte("x")});if e!=nil{t.Fatal(e)};want:=errors.New("stop");_,e=l.ScanHeaders(ScanHeadersRequest{Context:context.Background(),Callback:func(ScanEntry)error{return want}});if !errors.Is(e,want){t.Fatalf("got %v",e)}}
